"use client";
/**
 * Dot Loader: a small grid of dots that plays a painted timeline. Each frame
 * lists the dots that are lit; the loader steps through them at `frameTime`
 * and blends between frames the way `transition` says. Presets cover the
 * common shapes, and any timeline can be passed as `frames`.
 */
import { useEffect, useMemo, useState, type CSSProperties } from "react";

export type DotTransition = "step" | "fade" | "color";
export type DotPreset = "spinner" | "sweep" | "ripple";

/** The cells around the edge of an n×n grid, clockwise from the top left. */
function ring(n: number): number[] {
  if (n === 1) return [0];
  const top = Array.from({ length: n }, (_, c) => c);
  const right = Array.from({ length: n - 2 }, (_, r) => (r + 1) * n + n - 1);
  const bottom = Array.from({ length: n }, (_, c) => (n - 1) * n + (n - 1 - c));
  const left = Array.from({ length: n - 2 }, (_, r) => (n - 2 - r) * n);
  return [...top, ...right, ...bottom, ...left];
}

/** A timeline for one of the presets on an n×n grid. Each frame lists lit cells. */
export function dotFrames(preset: DotPreset, n: number): number[][] {
  const cells = Array.from({ length: n * n }, (_, i) => i);
  if (preset === "spinner") {
    // A snake as long as one side runs around the edge.
    const path = ring(n);
    return path.map((_, f) => Array.from({ length: n }, (_, k) => path[(f + k) % path.length]));
  }
  if (preset === "sweep") {
    // A diagonal band crosses the grid, then the grid rests empty for a beat.
    const frames = Array.from({ length: 2 * n - 1 }, (_, f) => cells.filter((i) => Math.floor(i / n) + (i % n) === f || Math.floor(i / n) + (i % n) === f - 1));
    return [...frames, cells.filter((i) => Math.floor(i / n) + (i % n) === 2 * n - 2), []];
  }
  // Ripple: rings grow out of the centre.
  const c = (n - 1) / 2;
  const dist = (i: number) => Math.max(Math.abs(Math.floor(i / n) - c), Math.abs((i % n) - c));
  const rings = [...new Set(cells.map((i) => Math.round(dist(i) * 2)))].sort((a, b) => a - b);
  return [...rings.map((r) => cells.filter((i) => Math.round(dist(i) * 2) === r)), []];
}

export interface DotLoaderProps {
  /** Dots per side. */
  grid?: number;
  /** One of the presets; ignored when `frames` is given. */
  preset?: DotPreset;
  /** A painted timeline: each frame lists the lit cells, row by row from 0. */
  frames?: number[][];
  /** Milliseconds per frame. */
  frameTime?: number;
  /** Milliseconds a dot takes to change. */
  blend?: number;
  /** Hard steps, an opacity fade, or a fade between the two colours. */
  transition?: DotTransition;
  active?: string;
  inactive?: string;
  /** Dot diameter in pixels. */
  dot?: number;
  /** Space between dots; defaults to half a dot. */
  gap?: number;
  playing?: boolean;
  /** Read by assistive technology. */
  label?: string;
  className?: string;
  style?: CSSProperties;
}

export function DotLoader({
  grid = 3,
  preset = "spinner",
  frames,
  frameTime = 120,
  blend = 90,
  transition = "color",
  active = "#1a1a1c",
  inactive = "#e8e8ea",
  dot = 6,
  gap,
  playing = true,
  label = "Loading",
  className,
  style,
}: DotLoaderProps) {
  const n = Math.max(1, Math.round(grid));
  const timeline = useMemo(() => (frames?.length ? frames : dotFrames(preset, n)), [frames, preset, n]);
  const [frame, setFrame] = useState(0);
  const [still, setStill] = useState(false);

  useEffect(() => {
    const query = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    setStill(query?.matches === true);
    const change = (e: MediaQueryListEvent) => setStill(e.matches);
    query?.addEventListener("change", change);
    return () => query?.removeEventListener("change", change);
  }, []);

  useEffect(() => {
    setFrame(0);
    if (!playing || still || timeline.length < 2) return;
    const id = window.setInterval(() => setFrame((f) => (f + 1) % timeline.length), Math.max(16, frameTime));
    return () => window.clearInterval(id);
  }, [timeline, frameTime, playing, still]);

  const lit = new Set(timeline[frame % timeline.length] ?? []);
  const space = gap ?? dot / 2;
  const ease = transition === "step" ? "none" : `${transition === "fade" ? "opacity" : "background-color"} ${blend}ms ease-out`;

  return (
    <span
      role="status"
      aria-label={label}
      className={className}
      style={{ display: "inline-grid", gridTemplateColumns: `repeat(${n}, ${dot}px)`, gap: space, flex: "none", ...style }}
    >
      {Array.from({ length: n * n }, (_, i) => {
        const on = lit.has(i);
        return (
          <span
            key={i}
            aria-hidden="true"
            style={{
              width: dot,
              height: dot,
              borderRadius: "50%",
              transition: ease,
              background: transition === "fade" ? active : on ? active : inactive,
              opacity: transition === "fade" ? (on ? 1 : 0.14) : 1,
            }}
          />
        );
      })}
    </span>
  );
}
